tools.usage:
POST https://image.adobe.io/pie/psdService/<operation>
Headers: Authorization: Bearer <IMS token>, x-api-key: <client id>, Content-Type: application/json
Body: { "inputs": [{ "href": "<presigned GET url>", "storage": "external" }], "options": {...}, "outputs": [{ "href": "<presigned PUT url>", "storage": "external", "type": "image/jpeg" }] }

tools.example:
{
  "inputs": [{"href": "https://s3.../in.psd?sig", "storage": "external"}],
  "options": {"actions": [{"type": "uxp", "href": "https://s3.../resize.psjs?sig"}], "scriptOutputPattern": "out/*.jpg"},
  "outputs": [{"href": "https://s3.../result.psd?sig", "storage": "external", "type": "image/vnd.adobe.photoshop"}]
}
